-- ===========================================================================
-- KCO Sales & Learning Management System - complete schema
--
-- GENERATED by scripts/bundle-schema.sh from supabase/migrations/*.sql.
-- Do not edit this file; edit the migrations and regenerate.
--
-- REQUIREMENTS
--   * A DEDICATED Supabase project. This script issues schema-wide REVOKEs
--     and creates public.profiles; running it in a database shared with
--     another application will break that application.
--   * Run once, on an empty project. It is not idempotent - re-running raises
--     "already exists", which is the intended safety net.
-- ===========================================================================

-- The whole file runs in one transaction. Any error rolls it all back.
begin;

-- ###########################################################################
-- ## 20260910090000_extensions_and_enums.sql
-- ###########################################################################

-- ============================================================================
-- KCO Sales & Learning Management System
-- 0001 - Extensions, enums, and shared helper functions.
--
-- Every later migration depends on the vocabulary defined here. Enums are used
-- instead of free-text status columns so an invalid state cannot be written at
-- all, rather than being caught by application validation that a direct API
-- call would bypass.
-- ============================================================================

create extension if not exists "pgcrypto"  with schema extensions;  -- gen_random_uuid()
create extension if not exists "pg_trgm"   with schema extensions;  -- trigram search

-- ---------------------------------------------------------------- identity --

-- Exactly two roles (spec §8). Widening this is a deliberate migration, not a
-- config change, because every RLS policy in 0004 reads it.
create type public.user_role as enum ('admin', 'sales');

create type public.user_status as enum ('active', 'inactive', 'pending');

-- ----------------------------------------------------------------- content --

create type public.content_status as enum ('draft', 'published', 'archived');

create type public.difficulty as enum ('foundation', 'intermediate', 'advanced');

-- The block vocabulary the renderer understands. A block whose type is not in
-- this list cannot be stored, so the frontend never meets one it cannot draw.
create type public.block_type as enum (
  'heading',
  'text',
  'bullets',
  'numbered',
  'checklist',
  'callout',
  'dosdonts',
  'script',
  'comparison',
  'formula',
  'scenario',
  'quote',
  'quiz',
  'activity',
  'wording',
  'tip',
  'warning',
  'image',
  'video'
);

-- ------------------------------------------------------------- assessments --

create type public.question_type as enum (
  'multiple_choice',
  'true_false',
  'multiple_select',
  'short_answer'
);

create type public.attempt_status as enum ('in_progress', 'submitted', 'abandoned');

-- --------------------------------------------------------------- delivery ---

create type public.assignment_target as enum ('module', 'path', 'assessment', 'activity');

create type public.assignment_status as enum (
  'not-started',
  'in-progress',
  'completed',
  'overdue'
);

create type public.progress_state as enum ('not-started', 'in-progress', 'completed');

create type public.notification_kind as enum (
  'assignment',
  'announcement',
  'result',
  'content',
  'due',
  'mention'
);

create type public.announcement_priority as enum ('normal', 'important', 'critical');

-- ---------------------------------------------------------------- helpers ---

-- Keeps updated_at honest. Attached by trigger to every mutable table so an
-- application that forgets to set it cannot produce a stale timestamp.
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;


-- ###########################################################################
-- ## 20260910090100_profiles.sql
-- ###########################################################################

-- ============================================================================
-- 0002 - Profiles.
--
-- Supabase Auth owns identity (auth.users); this table owns everything the
-- product knows about a person. Credentials are never duplicated here (§10).
--
-- `id` is the auth user id rather than an independent surrogate key. That makes
-- `auth.uid() = id` the cheapest possible RLS predicate - no join, no subquery -
-- which matters because every policy in 0004 evaluates it on every row.
-- ============================================================================

create table public.profiles (
  id            uuid primary key references auth.users (id) on delete cascade,

  email         text        not null unique,
  full_name     text        not null check (length(trim(full_name)) between 1 and 120),
  display_name  text        check (length(trim(display_name)) between 1 and 60),
  avatar_url    text,

  role          public.user_role   not null default 'sales',
  status        public.user_status not null default 'pending',

  department    text,
  position      text,

  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  last_login_at timestamptz
);

comment on table public.profiles is
  'Application identity. One row per auth.users row; never stores credentials.';
comment on column public.profiles.role is
  'Authorization source of truth. Only an admin may change it (see 0004).';

create index profiles_role_idx    on public.profiles (role);
create index profiles_status_idx  on public.profiles (status);
create index profiles_created_idx on public.profiles (created_at desc);
-- Case-insensitive lookup for the admin user table's search box.
create index profiles_name_trgm_idx on public.profiles using gin (full_name extensions.gin_trgm_ops);

create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Role lookup used by every admin policy.
--
-- SECURITY DEFINER is required, not a convenience: a policy on `profiles` that
-- selected from `profiles` to find the caller's role would re-enter its own
-- RLS check and recurse. Running as the owner reads the row directly.
--
-- STABLE lets the planner call it once per statement instead of once per row.
-- ---------------------------------------------------------------------------
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.profiles p
    where p.id = auth.uid()
      and p.role = 'admin'
      and p.status = 'active'
  );
$$;

comment on function public.is_admin() is
  'True when the caller is an active admin. SECURITY DEFINER to avoid RLS recursion on profiles.';

-- Signed-in and not deactivated. Used wherever "any real user" is the bar.
create or replace function public.is_active_user()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.status = 'active'
  );
$$;

-- ---------------------------------------------------------------------------
-- Provisioning. Fires for both email/password signup and OAuth (§9), so a
-- Google sign-in lands with a profile already in place and the app never has
-- to handle a signed-in user with no profile row.
--
-- New accounts are always 'sales' + 'pending'. Self-promotion is impossible
-- here by construction; an admin activates and assigns the role afterwards.
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.profiles (id, email, full_name, avatar_url, role, status)
  values (
    new.id,
    new.email,
    -- OAuth providers use different keys for the same idea; fall back to the
    -- local-part of the address so full_name is never empty.
    coalesce(
      nullif(new.raw_user_meta_data ->> 'full_name', ''),
      nullif(new.raw_user_meta_data ->> 'name', ''),
      split_part(new.email, '@', 1)
    ),
    nullif(new.raw_user_meta_data ->> 'avatar_url', ''),
    'sales',
    'pending'
  )
  on conflict (id) do nothing;   -- idempotent: re-running signup is not an error
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Records the sign-in timestamp shown in the admin user table. Called by the
-- client after a successful session; safe for a user to run on their own row.
create or replace function public.touch_last_login()
returns void
language sql
security definer
set search_path = public, pg_temp
as $$
  update public.profiles set last_login_at = now() where id = auth.uid();
$$;


-- ###########################################################################
-- ## 20260910090200_content.sql
-- ###########################################################################

-- ============================================================================
-- 0003 - Learning content.
--
-- Shape:  categories -> modules -> lessons -> content_blocks
--         learning_paths -> learning_path_items -> (module | assessment)
--
-- Naming note: the DB calls the top-level unit a "module" (§11). The UI calls
-- the same thing a "Material" because that is the word the sidebar uses (§7).
-- One concept, two audiences; the mapping lives in the service layer.
-- ============================================================================

-- ------------------------------------------------------------- categories --

create table public.categories (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name        text not null check (length(trim(name)) between 1 and 80),
  description text not null default '',
  -- Token name, not a hex value: the theme resolves it, so dark mode keeps
  -- working and a category cannot introduce an off-palette colour.
  accent      text not null default 'slate'
                check (accent in ('green','blue','amber','violet','rose','slate')),
  icon        text not null default 'BookMarked',
  sort_order  int  not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create index categories_sort_idx on public.categories (sort_order, name);

create trigger categories_set_updated_at before update on public.categories
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------- modules --

create table public.modules (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title         text not null check (length(trim(title)) between 1 and 160),
  description   text not null default '',
  category_id   uuid references public.categories (id) on delete set null,

  module_number int  not null default 0,
  status        public.content_status not null default 'draft',
  difficulty    public.difficulty     not null default 'foundation',
  duration_minutes int not null default 0 check (duration_minutes >= 0),

  -- Who may see it, and which teams it is aimed at. Empty audience would hide
  -- a module from everyone, which is never intended, so it is disallowed.
  audience      public.user_role[] not null default array['admin','sales']::public.user_role[]
                  check (cardinality(audience) > 0),
  teams         text[] not null default '{}',
  tags          text[] not null default '{}',

  thumbnail_url text,
  icon          text,

  -- §44: set when the body contains an earnings/ROI style claim that management
  -- has not signed off. The UI badges it; it does not block publishing.
  needs_claim_review boolean not null default false,

  version       int  not null default 1 check (version >= 1),
  created_by    uuid references public.profiles (id) on delete set null,
  updated_by    uuid references public.profiles (id) on delete set null,
  published_by  uuid references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  published_at  timestamptz,

  -- A module cannot claim to be published without a publication timestamp;
  -- reports group by published_at and a null there would silently drop rows.
  constraint modules_published_has_timestamp
    check (status <> 'published' or published_at is not null)
);

create index modules_status_idx     on public.modules (status);
create index modules_category_idx   on public.modules (category_id);
create index modules_number_idx     on public.modules (module_number);
create index modules_updated_idx    on public.modules (updated_at desc);
-- Serves the library list, which is always filtered to published first.
create index modules_status_cat_idx on public.modules (status, category_id);
create index modules_title_trgm_idx on public.modules using gin (title extensions.gin_trgm_ops);
create index modules_tags_idx       on public.modules using gin (tags);

create trigger modules_set_updated_at before update on public.modules
  for each row execute function public.set_updated_at();

-- Stamps published_at/published_by the first time a module goes live, and
-- bumps version on every content-affecting edit (§58). Doing this in the
-- database means the metadata is right regardless of which client wrote.
create or replace function public.modules_publish_metadata()
returns trigger
language plpgsql
as $$
begin
  if new.status = 'published' and coalesce(old.status, 'draft') <> 'published' then
    new.published_at := coalesce(new.published_at, now());
    new.published_by := coalesce(new.published_by, auth.uid());
  end if;

  -- Republishing an archived module should not reset its original date, so
  -- published_at is never cleared here - only archived status changes.
  if new.title is distinct from old.title
     or new.description is distinct from old.description
     or new.status is distinct from old.status then
    new.version := old.version + 1;
  end if;

  new.updated_by := coalesce(auth.uid(), new.updated_by);
  return new;
end;
$$;

create trigger modules_publish_metadata
  before update on public.modules
  for each row execute function public.modules_publish_metadata();

-- ---------------------------------------------------------------- lessons --

create table public.lessons (
  id          uuid primary key default gen_random_uuid(),
  module_id   uuid not null references public.modules (id) on delete cascade,
  title       text not null check (length(trim(title)) between 1 and 160),
  summary     text not null default '',
  -- Position within the module. Unique per module so two lessons can never
  -- occupy the same slot and render in an arbitrary order.
  sort_order  int  not null default 0,
  status      public.content_status not null default 'published',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),

  constraint lessons_unique_order unique (module_id, sort_order) deferrable initially deferred
);

create index lessons_module_idx on public.lessons (module_id, sort_order);

create trigger lessons_set_updated_at before update on public.lessons
  for each row execute function public.set_updated_at();

-- --------------------------------------------------------- content_blocks --

-- One row per block (§14) rather than one HTML blob per lesson. The typed
-- column drives the renderer; `data` carries the shape that type requires.
-- Validation of `data` lives in the Zod schemas shared by editor and seed -
-- Postgres enforces the envelope, the application enforces the payload.
create table public.content_blocks (
  id         uuid primary key default gen_random_uuid(),
  lesson_id  uuid not null references public.lessons (id) on delete cascade,
  type       public.block_type not null,
  data       jsonb not null default '{}'::jsonb,
  sort_order int   not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint content_blocks_unique_order unique (lesson_id, sort_order) deferrable initially deferred
);

create index content_blocks_lesson_idx on public.content_blocks (lesson_id, sort_order);

create trigger content_blocks_set_updated_at before update on public.content_blocks
  for each row execute function public.set_updated_at();

-- --------------------------------------------------------- learning paths --

create table public.learning_paths (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title       text not null check (length(trim(title)) between 1 and 160),
  description text not null default '',
  audience    public.user_role[] not null default array['admin','sales']::public.user_role[],
  accent      text not null default 'slate'
                check (accent in ('green','blue','amber','violet','rose','slate')),
  status      public.content_status not null default 'draft',
  created_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  published_at timestamptz
);

create index learning_paths_status_idx on public.learning_paths (status);

create trigger learning_paths_set_updated_at before update on public.learning_paths
  for each row execute function public.set_updated_at();

-- A path step is either a module or an assessment, never both and never
-- neither - enforced below rather than left to the application.
create table public.learning_path_items (
  id         uuid primary key default gen_random_uuid(),
  path_id    uuid not null references public.learning_paths (id) on delete cascade,
  module_id  uuid references public.modules (id) on delete cascade,
  -- FK added in 0005, once assessments exists.
  assessment_id uuid,
  sort_order int not null default 0,
  required   boolean not null default true,

  constraint path_item_exactly_one_target check (
    (module_id is not null)::int + (assessment_id is not null)::int = 1
  ),
  constraint learning_path_items_unique_order unique (path_id, sort_order) deferrable initially deferred
);

create index learning_path_items_path_idx on public.learning_path_items (path_id, sort_order);


-- ###########################################################################
-- ## 20260910090300_assessments.sql
-- ###########################################################################

-- ============================================================================
-- 0004 - Assessments, attempts, and answers.
--
-- The security-critical detail in this file is that correct answers live in
-- `assessment_choices.is_correct` and `assessment_questions.correct_text`,
-- both of which are withheld from sales users by the policies in 0007. A
-- learner's client literally cannot read the key, so "don't reveal answers
-- before submission" (§17) is enforced by the database, not by careful UI.
-- ============================================================================

create table public.assessments (
  id             uuid primary key default gen_random_uuid(),
  slug           text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title          text not null check (length(trim(title)) between 1 and 160),
  description    text not null default '',
  instructions   text not null default '',
  module_id      uuid references public.modules (id) on delete set null,

  passing_score  int not null default 80 check (passing_score between 0 and 100),
  time_limit_minutes int check (time_limit_minutes is null or time_limit_minutes > 0),
  -- 0 means unlimited. Negative would be meaningless, so it is excluded.
  attempts_allowed int not null default 3 check (attempts_allowed >= 0),
  randomize_questions boolean not null default false,
  randomize_choices   boolean not null default false,
  show_correct_answers boolean not null default true,

  status         public.content_status not null default 'draft',
  version        int not null default 1,
  created_by     uuid references public.profiles (id) on delete set null,
  updated_by     uuid references public.profiles (id) on delete set null,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  published_at   timestamptz,

  constraint assessments_published_has_timestamp
    check (status <> 'published' or published_at is not null)
);

create index assessments_status_idx on public.assessments (status);
create index assessments_module_idx on public.assessments (module_id);

create trigger assessments_set_updated_at before update on public.assessments
  for each row execute function public.set_updated_at();

-- Deferred FK from 0003, now that the target exists.
alter table public.learning_path_items
  add constraint learning_path_items_assessment_fk
  foreign key (assessment_id) references public.assessments (id) on delete cascade;

-- -------------------------------------------------------------- questions --

create table public.assessment_questions (
  id            uuid primary key default gen_random_uuid(),
  assessment_id uuid not null references public.assessments (id) on delete cascade,
  type          public.question_type not null default 'multiple_choice',
  prompt        text not null check (length(trim(prompt)) > 0),
  explanation   text not null default '',
  points        int  not null default 1 check (points > 0),
  sort_order    int  not null default 0,

  -- Only used by 'short_answer'. Compared case-insensitively and trimmed by
  -- the scoring function below.
  correct_text  text,

  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),

  constraint questions_unique_order unique (assessment_id, sort_order) deferrable initially deferred,
  -- A short-answer question with no key cannot be scored, and a choice-based
  -- question with a key would be ambiguous.
  constraint questions_short_answer_has_key check (
    (type = 'short_answer' and correct_text is not null and length(trim(correct_text)) > 0)
    or (type <> 'short_answer' and correct_text is null)
  )
);

create index assessment_questions_assessment_idx
  on public.assessment_questions (assessment_id, sort_order);

create trigger assessment_questions_set_updated_at before update on public.assessment_questions
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------- choices --

create table public.assessment_choices (
  id          uuid primary key default gen_random_uuid(),
  question_id uuid not null references public.assessment_questions (id) on delete cascade,
  text        text not null check (length(trim(text)) > 0),
  is_correct  boolean not null default false,
  sort_order  int not null default 0,

  constraint choices_unique_order unique (question_id, sort_order) deferrable initially deferred
);

create index assessment_choices_question_idx on public.assessment_choices (question_id, sort_order);

-- Guards the builder's output at write time: a choice-based question must have
-- at least two options and the right number of correct ones. Without this a
-- half-finished question could be published and would be unscoreable.
create or replace function public.validate_question_choices(p_question_id uuid)
returns void
language plpgsql
as $$
declare
  q_type   public.question_type;
  n_total  int;
  n_correct int;
begin
  select type into q_type from public.assessment_questions where id = p_question_id;
  if q_type is null or q_type = 'short_answer' then
    return;
  end if;

  select count(*), count(*) filter (where is_correct)
    into n_total, n_correct
    from public.assessment_choices where question_id = p_question_id;

  if n_total < 2 then
    raise exception 'Question % needs at least two choices (has %)', p_question_id, n_total;
  end if;

  if q_type in ('multiple_choice', 'true_false') and n_correct <> 1 then
    raise exception 'Question % must have exactly one correct choice (has %)', p_question_id, n_correct;
  end if;

  if q_type = 'multiple_select' and n_correct < 1 then
    raise exception 'Question % must have at least one correct choice', p_question_id;
  end if;
end;
$$;

-- ---------------------------------------------------------------- attempts --

create table public.assessment_attempts (
  id             uuid primary key default gen_random_uuid(),
  assessment_id  uuid not null references public.assessments (id) on delete cascade,
  user_id        uuid not null references public.profiles (id) on delete cascade,

  attempt_number int not null check (attempt_number > 0),
  status         public.attempt_status not null default 'in_progress',

  -- Written only by submit_assessment_attempt(); see the policy in 0007 that
  -- prevents a learner from setting their own score.
  score          int,
  max_score      int,
  percentage     numeric(5,2),
  passed         boolean,

  started_at     timestamptz not null default now(),
  submitted_at   timestamptz,

  constraint attempts_unique_number unique (user_id, assessment_id, attempt_number),
  constraint attempts_submitted_is_scored check (
    status <> 'submitted'
    or (score is not null and percentage is not null and passed is not null and submitted_at is not null)
  )
);

create index attempts_user_idx       on public.assessment_attempts (user_id, submitted_at desc);
create index attempts_assessment_idx on public.assessment_attempts (assessment_id);
create index attempts_status_idx     on public.assessment_attempts (status);

-- ----------------------------------------------------------------- answers --

create table public.assessment_answers (
  id           uuid primary key default gen_random_uuid(),
  attempt_id   uuid not null references public.assessment_attempts (id) on delete cascade,
  question_id  uuid not null references public.assessment_questions (id) on delete cascade,

  -- Choice ids for choice questions; free text for short answers.
  choice_ids   uuid[] not null default '{}',
  text_answer  text,

  -- Filled in by the scoring function at submission, not by the client.
  is_correct   boolean,
  points_awarded int not null default 0,

  answered_at  timestamptz not null default now(),

  constraint answers_unique_question unique (attempt_id, question_id)
);

create index assessment_answers_attempt_idx on public.assessment_answers (attempt_id);

-- ---------------------------------------------------------------------------
-- Scoring.
--
-- Runs SECURITY DEFINER so it can read is_correct, which the calling learner
-- cannot. This is the only path by which a score is ever written: the RLS
-- policy in 0007 forbids a client from updating score/passed directly, so a
-- learner cannot award themselves a pass.
-- ---------------------------------------------------------------------------
create or replace function public.submit_assessment_attempt(p_attempt_id uuid)
returns public.assessment_attempts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_attempt public.assessment_attempts;
  v_pass    int;
  v_total   int := 0;
  v_earned  int := 0;
  v_pct     numeric(5,2);
  r         record;
begin
  select * into v_attempt from public.assessment_attempts where id = p_attempt_id for update;

  if v_attempt is null then
    raise exception 'Attempt % not found', p_attempt_id;
  end if;

  -- An attempt belongs to exactly one person and only they may submit it.
  if v_attempt.user_id <> auth.uid() then
    raise exception 'You cannot submit an attempt that is not yours';
  end if;

  if v_attempt.status <> 'in_progress' then
    raise exception 'This attempt has already been submitted';
  end if;

  select passing_score into v_pass from public.assessments where id = v_attempt.assessment_id;

  -- Score every question on the assessment, not merely the answered ones, so
  -- skipping a question costs its points rather than shrinking the denominator.
  for r in
    select q.id, q.type, q.points, q.correct_text,
           a.choice_ids, a.text_answer
      from public.assessment_questions q
      left join public.assessment_answers a
        on a.question_id = q.id and a.attempt_id = p_attempt_id
     where q.assessment_id = v_attempt.assessment_id
  loop
    v_total := v_total + r.points;

    declare
      v_ok boolean := false;
      v_correct uuid[];
    begin
      if r.type = 'short_answer' then
        v_ok := r.text_answer is not null
                and lower(trim(r.text_answer)) = lower(trim(r.correct_text));
      else
        select coalesce(array_agg(c.id order by c.id), '{}')
          into v_correct
          from public.assessment_choices c
         where c.question_id = r.id and c.is_correct;

        -- Set equality: every correct choice selected and nothing else. For
        -- multiple_select this means partial credit is not awarded, which
        -- matches how the results screen reports a question as right or wrong.
        v_ok := v_correct <> '{}'
                and (select coalesce(array_agg(x order by x), '{}')
                       from unnest(coalesce(r.choice_ids, '{}')) x) = v_correct;
      end if;

      if v_ok then
        v_earned := v_earned + r.points;
      end if;

      -- Record the verdict so the review screen does not re-derive it.
      update public.assessment_answers
         set is_correct = v_ok,
             points_awarded = case when v_ok then r.points else 0 end
       where attempt_id = p_attempt_id and question_id = r.id;
    end;
  end loop;

  v_pct := case when v_total > 0 then round((v_earned::numeric / v_total) * 100, 2) else 0 end;

  update public.assessment_attempts
     set status = 'submitted',
         score = v_earned,
         max_score = v_total,
         percentage = v_pct,
         passed = v_pct >= v_pass,
         submitted_at = now()
   where id = p_attempt_id
   returning * into v_attempt;

  return v_attempt;
end;
$$;

-- Opens an attempt, allocating the next attempt number and refusing to exceed
-- the configured limit. Server-side because the limit is a rule, not a hint.
create or replace function public.start_assessment_attempt(p_assessment_id uuid)
returns public.assessment_attempts
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_allowed int;
  v_status  public.content_status;
  v_used    int;
  v_attempt public.assessment_attempts;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select attempts_allowed, status into v_allowed, v_status
    from public.assessments where id = p_assessment_id;

  if v_status is null then
    raise exception 'Assessment not found';
  end if;

  -- Admins may open a draft to test it; learners may not.
  if v_status <> 'published' and not public.is_admin() then
    raise exception 'This assessment is not available';
  end if;

  select count(*) into v_used
    from public.assessment_attempts
   where user_id = auth.uid() and assessment_id = p_assessment_id
     and status = 'submitted';

  if v_allowed > 0 and v_used >= v_allowed then
    raise exception 'You have used all % attempts for this assessment', v_allowed;
  end if;

  -- Reuse an abandoned in-progress attempt rather than stacking up rows when
  -- a learner closes the tab and comes back.
  select * into v_attempt
    from public.assessment_attempts
   where user_id = auth.uid() and assessment_id = p_assessment_id and status = 'in_progress'
   order by started_at desc limit 1;

  if v_attempt.id is not null then
    return v_attempt;
  end if;

  insert into public.assessment_attempts (assessment_id, user_id, attempt_number)
  values (p_assessment_id, auth.uid(), v_used + 1)
  returning * into v_attempt;

  return v_attempt;
end;
$$;


-- ###########################################################################
-- ## 20260910090400_training_and_resources.sql
-- ###########################################################################

-- ============================================================================
-- 0005 - Training activities, practice scenarios, and the sales resource
--        libraries (objections, scripts, wording, quick reference, Sales Bible,
--        competencies).
--
-- These are all admin-authored reference content with the same lifecycle as a
-- module, so they share the content_status enum and the published/draft rules.
-- ============================================================================

-- ----------------------------------------------------- training activities --

create table public.training_activities (
  id               uuid primary key default gen_random_uuid(),
  slug             text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title            text not null check (length(trim(title)) between 1 and 160),
  objective        text not null default '',
  description      text not null default '',
  duration_minutes int  not null default 15 check (duration_minutes > 0),
  participants     text not null default '',
  difficulty       public.difficulty not null default 'foundation',
  instructions     text[] not null default '{}',
  facilitator_notes text[] not null default '{}',
  expected_outcome text not null default '',
  materials        text[] not null default '{}',
  tags             text[] not null default '{}',
  category_id      uuid references public.categories (id) on delete set null,
  status           public.content_status not null default 'draft',
  created_by       uuid references public.profiles (id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

create index training_activities_status_idx on public.training_activities (status);
create index training_activities_tags_idx   on public.training_activities using gin (tags);

create trigger training_activities_set_updated_at before update on public.training_activities
  for each row execute function public.set_updated_at();

-- ------------------------------------------------------ practice scenarios --

-- §21: seeded with scripted branches today. `turns` is jsonb precisely so an
-- AI roleplay engine can later generate turns at runtime without a migration -
-- the table shape does not encode the assumption that they are pre-written.
create table public.practice_scenarios (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title       text not null,
  channel     text not null check (channel in ('phone','chat','objection')),
  personality text not null,
  difficulty  public.difficulty not null default 'foundation',
  setup       text not null default '',
  goal        text not null default '',
  turns       jsonb not null default '[]'::jsonb,
  coaching    text[] not null default '{}',
  status      public.content_status not null default 'draft',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create index practice_scenarios_status_idx on public.practice_scenarios (status);

create trigger practice_scenarios_set_updated_at before update on public.practice_scenarios
  for each row execute function public.set_updated_at();

-- Records a run so "practice regular" progress and admin reporting have data.
create table public.scenario_runs (
  id          uuid primary key default gen_random_uuid(),
  scenario_id uuid not null references public.practice_scenarios (id) on delete cascade,
  user_id     uuid not null references public.profiles (id) on delete cascade,
  best_count  int not null default 0,
  turn_count  int not null default 0,
  completed_at timestamptz not null default now()
);

create index scenario_runs_user_idx on public.scenario_runs (user_id, completed_at desc);

-- --------------------------------------------------------------- objections --

create table public.objections (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique,
  objection   text not null,
  -- The concern underneath the words - the thing the rep actually answers.
  translation text not null default '',
  category    text not null default 'price'
                check (category in ('price','risk','capability','competition','capital','timing','market')),
  frequency   text not null default 'medium'
                check (frequency in ('very-high','high','medium','low')),
  difficulty  public.difficulty not null default 'foundation',

  -- A.C.A.C. (§23). Stored as four columns rather than one blob because the
  -- resource page renders them as four labelled steps and admins edit them
  -- individually.
  acknowledge text not null default '',
  clarify     text not null default '',
  address     text not null default '',
  close       text not null default '',

  pitfalls    text[] not null default '{}',
  notes       text not null default '',
  -- §44: the answer touches earnings/ROI and must stay illustrative.
  claim_sensitive boolean not null default false,
  status      public.content_status not null default 'published',
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create index objections_category_idx on public.objections (category);
create index objections_status_idx   on public.objections (status);
create index objections_trgm_idx     on public.objections using gin (objection extensions.gin_trgm_ops);

create trigger objections_set_updated_at before update on public.objections
  for each row execute function public.set_updated_at();

-- ------------------------------------------------------------------ scripts --

-- §24: scripts live in the database, never inside a React component, so an
-- admin can fix wording without a deploy.
create table public.scripts (
  id         uuid primary key default gen_random_uuid(),
  slug       text not null unique,
  title      text not null,
  kind       text not null check (kind in
               ('phone','chat','closing','qualification','follow-up','complaint','wording')),
  channel    text not null default 'both' check (channel in ('phone','chat','both')),
  situation  text not null default '',
  language   text not null default 'mixed' check (language in ('en','fil','mixed')),
  lines      text[] not null default '{}',
  notes      text not null default '',
  tags       text[] not null default '{}',
  status     public.content_status not null default 'published',
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index scripts_kind_idx   on public.scripts (kind, sort_order);
create index scripts_status_idx on public.scripts (status);
create index scripts_trgm_idx   on public.scripts using gin (title extensions.gin_trgm_ops);

create trigger scripts_set_updated_at before update on public.scripts
  for each row execute function public.set_updated_at();

-- Avoid/use pairs for professional wording.
create table public.wording_pairs (
  id      uuid primary key default gen_random_uuid(),
  avoid   text not null,
  use     text not null,
  context text not null default 'both' check (context in ('phone','chat','both')),
  note    text not null default '',
  tags    text[] not null default '{}',
  sort_order int not null default 0,
  status  public.content_status not null default 'published'
);

-- ---------------------------------------------------------- quick reference --

create table public.quick_reference_items (
  id         uuid primary key default gen_random_uuid(),
  slug       text not null unique,
  title      text not null,
  kicker     text not null default '',
  kind       text not null check (kind in ('script','formula','checklist','rule')),
  channel    text not null default 'both' check (channel in ('phone','chat','both')),
  -- Same block vocabulary as a lesson, so the renderer is shared.
  blocks     jsonb not null default '[]'::jsonb,
  sort_order int not null default 0,
  status     public.content_status not null default 'published',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index quick_reference_status_idx on public.quick_reference_items (status, sort_order);

create trigger quick_reference_set_updated_at before update on public.quick_reference_items
  for each row execute function public.set_updated_at();

-- ------------------------------------------------------------- sales bible --

-- §45/§78. Sections are seeded; entries are deliberately allowed to be empty
-- so the UI can show "Content not yet configured" instead of an invented price.
create table public.sales_bible_sections (
  id         uuid primary key default gen_random_uuid(),
  slug       text not null unique,
  title      text not null,
  summary    text not null default '',
  sort_order int not null default 0
);

create table public.sales_bible_entries (
  id         uuid primary key default gen_random_uuid(),
  section_id uuid not null references public.sales_bible_sections (id) on delete cascade,
  label      text not null,
  -- Null (not empty string) means "no verified value has been supplied".
  -- The distinction matters: it is what the UI keys off to render the
  -- "Admin content required" state rather than a blank line (§78).
  value      text,
  detail     text not null default '',
  -- True once management has confirmed the value is accurate and publishable.
  verified   boolean not null default false,
  requires_approval boolean not null default false,
  sort_order int not null default 0,
  updated_by uuid references public.profiles (id) on delete set null,
  updated_at timestamptz not null default now()
);

create index sales_bible_entries_section_idx on public.sales_bible_entries (section_id, sort_order);

create trigger sales_bible_entries_set_updated_at before update on public.sales_bible_entries
  for each row execute function public.set_updated_at();

-- ------------------------------------------------------------ competencies --

-- §31/§32: the 1-5 scale is a property of the framework, so the level labels
-- live in their own table rather than being hard-coded in the report page.
create table public.competency_levels (
  level int primary key check (level between 1 and 5),
  label text not null,
  description text not null default ''
);

create table public.competencies (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique,
  name        text not null,
  definition  text not null default '',
  cluster     text not null default 'sales'
                check (cluster in ('core','sales','chat','service')),
  behavioral_indicators text[] not null default '{}',
  sort_order  int not null default 0,
  status      public.content_status not null default 'published'
);

create table public.user_competencies (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references public.profiles (id) on delete cascade,
  competency_id uuid not null references public.competencies (id) on delete cascade,
  level         int  not null check (level between 1 and 5),
  assessed_by   uuid references public.profiles (id) on delete set null,
  note          text not null default '',
  assessed_at   timestamptz not null default now(),

  constraint user_competencies_unique unique (user_id, competency_id)
);

create index user_competencies_user_idx on public.user_competencies (user_id);


-- ###########################################################################
-- ## 20260910090500_delivery_and_tracking.sql
-- ###########################################################################

-- ============================================================================
-- 0006 - Assignments, progress, favourites, notifications, announcements,
--        and the activity log.
--
-- This is the layer that turns published content into a person's workload and
-- records what they did with it.
-- ============================================================================

-- ------------------------------------------------------------- assignments --

create table public.assignments (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.profiles (id) on delete cascade,
  target_type  public.assignment_target not null,
  -- Polymorphic by design: a single "my assignments" query should not need a
  -- four-way union. Referential integrity is enforced by the trigger below,
  -- since a FK cannot point at four different tables.
  target_id    uuid not null,

  assigned_by  uuid references public.profiles (id) on delete set null,
  assigned_at  timestamptz not null default now(),
  due_at       timestamptz,
  status       public.assignment_status not null default 'not-started',
  note         text not null default '',
  completed_at timestamptz,

  -- Re-assigning the same thing to the same person should update, not stack.
  constraint assignments_unique_target unique (user_id, target_type, target_id)
);

create index assignments_user_idx    on public.assignments (user_id, status);
create index assignments_status_idx  on public.assignments (status);
create index assignments_due_idx     on public.assignments (due_at);
create index assignments_target_idx  on public.assignments (target_type, target_id);

-- Stands in for the foreign key a polymorphic column cannot have. Without it
-- an assignment could point at a deleted or non-existent module and the
-- learner's dashboard would show a row that opens nothing.
create or replace function public.assignments_check_target()
returns trigger
language plpgsql
as $$
declare
  v_exists boolean;
begin
  select case new.target_type
    when 'module'     then exists (select 1 from public.modules             where id = new.target_id)
    when 'path'       then exists (select 1 from public.learning_paths      where id = new.target_id)
    when 'assessment' then exists (select 1 from public.assessments         where id = new.target_id)
    when 'activity'   then exists (select 1 from public.training_activities where id = new.target_id)
  end into v_exists;

  if not v_exists then
    raise exception 'No % exists with id %', new.target_type, new.target_id;
  end if;
  return new;
end;
$$;

create trigger assignments_check_target
  before insert or update of target_type, target_id on public.assignments
  for each row execute function public.assignments_check_target();

-- Derives 'overdue' rather than storing it, so an assignment becomes overdue
-- by the passage of time instead of by a cron job that might not have run.
create or replace function public.assignment_effective_status(
  p_status public.assignment_status,
  p_due_at timestamptz
) returns public.assignment_status
language sql
immutable
as $$
  select case
    when p_status = 'completed' then 'completed'::public.assignment_status
    when p_due_at is not null and p_due_at < now() then 'overdue'::public.assignment_status
    else p_status
  end;
$$;

-- ---------------------------------------------------------------- progress --

-- One row per (learner, module). Lesson-level detail lives in
-- lesson_progress; this table carries the roll-up the dashboard reads.
create table public.module_progress (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles (id) on delete cascade,
  module_id  uuid not null references public.modules (id) on delete cascade,
  state      public.progress_state not null default 'not-started',
  started_at timestamptz,
  completed_at timestamptz,
  last_viewed_at timestamptz,
  last_viewed_lesson_id uuid references public.lessons (id) on delete set null,
  updated_at timestamptz not null default now(),

  constraint module_progress_unique unique (user_id, module_id)
);

create index module_progress_user_idx   on public.module_progress (user_id, state);
create index module_progress_module_idx on public.module_progress (module_id);

create trigger module_progress_set_updated_at before update on public.module_progress
  for each row execute function public.set_updated_at();

create table public.lesson_progress (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.profiles (id) on delete cascade,
  lesson_id    uuid not null references public.lessons (id) on delete cascade,
  module_id    uuid not null references public.modules (id) on delete cascade,
  completed    boolean not null default false,
  completed_at timestamptz,
  updated_at   timestamptz not null default now(),

  constraint lesson_progress_unique unique (user_id, lesson_id)
);

create index lesson_progress_user_module_idx on public.lesson_progress (user_id, module_id);

create trigger lesson_progress_set_updated_at before update on public.lesson_progress
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Roll-up. Marking a lesson complete recomputes the parent module's state in
-- the same transaction, so the two can never disagree - which they would if
-- the client wrote both and the second call failed.
-- ---------------------------------------------------------------------------
create or replace function public.sync_module_progress()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_total int;
  v_done  int;
  v_state public.progress_state;
begin
  select count(*) into v_total
    from public.lessons where module_id = new.module_id and status <> 'archived';

  select count(*) into v_done
    from public.lesson_progress lp
    join public.lessons l on l.id = lp.lesson_id and l.status <> 'archived'
   where lp.user_id = new.user_id and lp.module_id = new.module_id and lp.completed;

  v_state := case
    when v_total > 0 and v_done >= v_total then 'completed'
    when v_done > 0 then 'in-progress'
    else 'not-started'
  end;

  insert into public.module_progress as mp
    (user_id, module_id, state, started_at, completed_at, last_viewed_at, last_viewed_lesson_id)
  values (
    new.user_id, new.module_id, v_state,
    now(),
    case when v_state = 'completed' then now() end,
    now(), new.lesson_id
  )
  on conflict (user_id, module_id) do update set
    state = v_state,
    -- started_at is set once and never moved, so "when did you begin" survives.
    started_at = coalesce(mp.started_at, now()),
    completed_at = case
      when v_state = 'completed' then coalesce(mp.completed_at, now())
      else null
    end,
    last_viewed_at = now(),
    last_viewed_lesson_id = new.lesson_id;

  -- Completing the last lesson of an assigned module closes the assignment.
  if v_state = 'completed' then
    update public.assignments
       set status = 'completed', completed_at = now()
     where user_id = new.user_id
       and target_type = 'module'
       and target_id = new.module_id
       and status <> 'completed';
  end if;

  return new;
end;
$$;

create trigger lesson_progress_sync_module
  after insert or update on public.lesson_progress
  for each row execute function public.sync_module_progress();

-- --------------------------------------------------------------- favourites --

-- Polymorphic like assignments, and for the same reason: one query powers the
-- learner's favourites list across five content types.
create table public.favorites (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.profiles (id) on delete cascade,
  target_type  text not null check (target_type in
                 ('module','lesson','script','objection','quick_reference','activity')),
  target_id    uuid not null,
  created_at   timestamptz not null default now(),

  constraint favorites_unique unique (user_id, target_type, target_id)
);

create index favorites_user_idx on public.favorites (user_id, target_type);

-- ------------------------------------------------------------ notifications --

create table public.notifications (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles (id) on delete cascade,
  kind       public.notification_kind not null,
  title      text not null,
  body       text not null default '',
  href       text,
  read       boolean not null default false,
  created_at timestamptz not null default now()
);

-- Partial index: the bell only ever counts unread rows, so indexing read ones
-- would be dead weight.
create index notifications_unread_idx
  on public.notifications (user_id, created_at desc) where not read;
create index notifications_user_idx on public.notifications (user_id, created_at desc);

-- ----------------------------------------------------------- announcements --

create table public.announcements (
  id           uuid primary key default gen_random_uuid(),
  title        text not null,
  content      text not null default '',
  priority     public.announcement_priority not null default 'normal',
  audience     public.user_role[] not null default array['admin','sales']::public.user_role[],
  status       public.content_status not null default 'draft',
  created_by   uuid references public.profiles (id) on delete set null,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  published_at timestamptz,
  expires_at   timestamptz,

  constraint announcements_expiry_after_publish
    check (expires_at is null or published_at is null or expires_at > published_at)
);

create index announcements_status_idx on public.announcements (status, published_at desc);

create trigger announcements_set_updated_at before update on public.announcements
  for each row execute function public.set_updated_at();

-- ------------------------------------------------------------ activity log --

-- §38: meaningful events only. Page views are not logged.
create table public.activity_logs (
  id           uuid primary key default gen_random_uuid(),
  actor_id     uuid references public.profiles (id) on delete set null,
  action       text not null,
  entity_type  text not null default '',
  entity_id    uuid,
  target_label text not null default '',
  meta         jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now()
);

create index activity_logs_created_idx on public.activity_logs (created_at desc);
create index activity_logs_actor_idx   on public.activity_logs (actor_id, created_at desc);
create index activity_logs_action_idx  on public.activity_logs (action);

-- Writes an audit row as the caller. SECURITY DEFINER because the RLS policy
-- on activity_logs denies direct inserts to sales users - they must not be
-- able to forge an entry, but their genuine actions still need recording.
create or replace function public.log_activity(
  p_action text,
  p_entity_type text default '',
  p_entity_id uuid default null,
  p_target_label text default '',
  p_meta jsonb default '{}'::jsonb
) returns void
language sql
security definer
set search_path = public, pg_temp
as $$
  insert into public.activity_logs (actor_id, action, entity_type, entity_id, target_label, meta)
  values (auth.uid(), p_action, p_entity_type, p_entity_id, p_target_label, p_meta);
$$;


-- ###########################################################################
-- ## 20260910090600_rls.sql
-- ###########################################################################

-- ============================================================================
-- 0007 - Row Level Security.
--
-- Everything below is the real authorization boundary. The React route guards
-- are a usability feature; this file is the security control (§39).
--
-- Two predicates do most of the work:
--   public.is_admin()        - active admin
--   public.is_active_user()  - any signed-in, non-deactivated account
--
-- Deactivating a profile therefore revokes data access immediately, without
-- needing to delete the auth user or wait for their JWT to expire.
--
-- Reading order: each table gets (1) enable RLS, (2) read policies, (3) write
-- policies. A table with RLS enabled and no matching policy denies by default,
-- which is the behaviour we want for anything not listed.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Baseline privileges.
--
-- Supabase grants the anon/authenticated roles broad table access by default.
-- We keep that (RLS is what constrains it) but revoke it from `anon` outright:
-- nothing in this product is public, so an unauthenticated request should fail
-- at the privilege layer before any policy is even consulted.
--
-- !! REQUIRES A DEDICATED SUPABASE PROJECT !!
--
-- The two statements below are schema-wide. Run in a database that also hosts
-- another application and they will strip anonymous access from that
-- application's tables and functions too - which for a public storefront means
-- taking it offline for logged-out visitors. This migration set also creates
-- `public.profiles`, which collides with the table most Supabase starter
-- templates already define.
--
-- If the LMS ever has to share a project, replace these with explicit
-- per-object REVOKEs against the tables this schema owns.
-- ---------------------------------------------------------------------------
revoke all on all tables in schema public from anon;

-- Functions are EXECUTE-able by PUBLIC unless told otherwise, and `anon`
-- inherits that. Revoking from the role alone leaves the PUBLIC grant in
-- place and changes nothing, so PUBLIC has to be named explicitly.
revoke all on all functions in schema public from public, anon;

-- =========================================================== profiles ======

alter table public.profiles enable row level security;

-- Everyone signed in can see the team roster. This is an internal company
-- tool: names, roles and departments are not secrets, and the assignment UI
-- needs them. Progress and results are guarded separately below.
create policy profiles_select_self_or_active on public.profiles
  for select to authenticated
  using (id = auth.uid() or public.is_active_user());

-- A user may edit their own profile, but NOT their role or status - those are
-- the two columns that would let them promote themselves (§56). The WITH CHECK
-- re-reads the committed row and rejects the write if either changed.
create policy profiles_update_self on public.profiles
  for update to authenticated
  using (id = auth.uid())
  with check (
    id = auth.uid()
    and role   = (select p.role   from public.profiles p where p.id = auth.uid())
    and status = (select p.status from public.profiles p where p.id = auth.uid())
  );

create policy profiles_admin_all on public.profiles
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- Admins create profiles through the invite flow; the signup trigger inserts
-- as the definer, so no general INSERT policy is needed for self-signup.

-- ========================================================== content ========
--
-- Read rule for every content table: admins see everything, learners see only
-- what is published. Write rule: admins only.
-- ---------------------------------------------------------------------------

alter table public.categories enable row level security;

create policy categories_select on public.categories
  for select to authenticated using (public.is_active_user());
create policy categories_admin on public.categories
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------- modules --

alter table public.modules enable row level security;

create policy modules_select_published on public.modules
  for select to authenticated
  using (
    public.is_admin()
    or (
      public.is_active_user()
      and status = 'published'
      -- Honour the module's audience list, so an admin-only module stays
      -- invisible to sales even once published.
      and (select p.role from public.profiles p where p.id = auth.uid()) = any (audience)
    )
  );

create policy modules_admin on public.modules
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------- lessons --

-- A lesson is visible exactly when its module is. Expressed as an EXISTS over
-- modules so the module policy above is the single place the rule is written -
-- change it once and lessons follow.
alter table public.lessons enable row level security;

create policy lessons_select on public.lessons
  for select to authenticated
  using (
    public.is_admin()
    or (
      status = 'published'
      and exists (select 1 from public.modules m where m.id = module_id)
    )
  );

create policy lessons_admin on public.lessons
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- --------------------------------------------------------- content_blocks --

alter table public.content_blocks enable row level security;

create policy content_blocks_select on public.content_blocks
  for select to authenticated
  using (
    public.is_admin()
    or exists (select 1 from public.lessons l where l.id = lesson_id)
  );

create policy content_blocks_admin on public.content_blocks
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------- learning paths --

alter table public.learning_paths enable row level security;

create policy learning_paths_select on public.learning_paths
  for select to authenticated
  using (
    public.is_admin()
    or (public.is_active_user() and status = 'published'
        and (select p.role from public.profiles p where p.id = auth.uid()) = any (audience))
  );

create policy learning_paths_admin on public.learning_paths
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

alter table public.learning_path_items enable row level security;

create policy learning_path_items_select on public.learning_path_items
  for select to authenticated
  using (public.is_admin() or exists (select 1 from public.learning_paths p where p.id = path_id));

create policy learning_path_items_admin on public.learning_path_items
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- ======================================================== assessments =====

alter table public.assessments enable row level security;

create policy assessments_select on public.assessments
  for select to authenticated
  using (public.is_admin() or (public.is_active_user() and status = 'published'));

create policy assessments_admin on public.assessments
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

alter table public.assessment_questions enable row level security;

create policy assessment_questions_select on public.assessment_questions
  for select to authenticated
  using (public.is_admin() or exists (select 1 from public.assessments a where a.id = assessment_id));

create policy assessment_questions_admin on public.assessment_questions
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

alter table public.assessment_choices enable row level security;

create policy assessment_choices_select on public.assessment_choices
  for select to authenticated
  using (
    public.is_admin()
    or exists (
      select 1 from public.assessment_questions q where q.id = question_id
    )
  );

create policy assessment_choices_admin on public.assessment_choices
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- Hiding the answer key.
--
-- RLS filters rows, not columns - and a learner must be able to read the
-- choice rows in order to see the options. So the key is protected with
-- column privileges instead: `authenticated` simply has no SELECT right on
-- assessment_choices.is_correct or assessment_questions.correct_text.
--
-- The effect is that `select * from assessment_choices` fails for everyone,
-- and a learner has no query at all that returns the key - not a filtered one,
-- not a crafted one. There is no policy to get wrong.
--
-- Admins reach the key through the two definer views below, which re-admit it
-- behind an explicit is_admin() check.
-- ---------------------------------------------------------------------------
-- The table-level grant must go first. A column-level REVOKE against a role
-- that holds SELECT on the whole table does nothing at all - table-level
-- SELECT already covers every column, including ones added later. Supabase
-- grants exactly that to `authenticated` by default, so the sequence is:
-- drop the table-wide right, then hand back only the safe columns.
revoke select on public.assessment_choices   from authenticated;
revoke select on public.assessment_questions from authenticated;

grant select (id, question_id, text, sort_order)
  on public.assessment_choices to authenticated;
grant select (id, assessment_id, type, prompt, explanation, points, sort_order, created_at, updated_at)
  on public.assessment_questions to authenticated;

-- Definer views: they run as the owner, so they can read the withheld columns,
-- and their own WHERE clause is what limits them to admins.
create view public.admin_assessment_choices
  with (security_invoker = false) as
  select c.id, c.question_id, c.text, c.is_correct, c.sort_order
    from public.assessment_choices c
   where public.is_admin();

create view public.admin_assessment_questions
  with (security_invoker = false) as
  select q.id, q.assessment_id, q.type, q.prompt, q.explanation,
         q.points, q.sort_order, q.correct_text
    from public.assessment_questions q
   where public.is_admin();

revoke all on public.admin_assessment_choices   from anon;
revoke all on public.admin_assessment_questions from anon;
grant select on public.admin_assessment_choices   to authenticated;
grant select on public.admin_assessment_questions to authenticated;

comment on view public.admin_assessment_choices is
  'Admin-only read path for assessment_choices.is_correct, which is revoked from authenticated.';

-- ------------------------------------------------------------- attempts ----

alter table public.assessment_attempts enable row level security;

-- A learner sees only their own attempts (§39). Admins see all, which is what
-- the assessment-performance report is built on.
create policy attempts_select_own on public.assessment_attempts
  for select to authenticated
  using (user_id = auth.uid() or public.is_admin());

-- Attempts are opened by start_assessment_attempt(), which is definer, so no
-- INSERT policy is granted to learners - they cannot fabricate an attempt row
-- with a chosen attempt_number.
create policy attempts_admin on public.assessment_attempts
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- The one thing a learner may change directly is abandoning their own attempt.
-- Scoring columns are pinned to their current values, so this update can never
-- be used to write a score - only submit_assessment_attempt() does that.
create policy attempts_abandon_own on public.assessment_attempts
  for update to authenticated
  using (user_id = auth.uid() and status = 'in_progress')
  with check (
    user_id = auth.uid()
    and status in ('in_progress', 'abandoned')
    and score is null
    and passed is null
    and percentage is null
  );

-- -------------------------------------------------------------- answers ----

alter table public.assessment_answers enable row level security;

create policy answers_select_own on public.assessment_answers
  for select to authenticated
  using (
    public.is_admin()
    or exists (
      select 1 from public.assessment_attempts t
       where t.id = attempt_id and t.user_id = auth.uid()
    )
  );

-- A learner may record and change answers only while their own attempt is
-- still open. Once submitted, the attempt is frozen: the USING clause stops
-- matching, so no further write is possible.
create policy answers_write_own_open_attempt on public.assessment_answers
  for insert to authenticated
  with check (
    exists (
      select 1 from public.assessment_attempts t
       where t.id = attempt_id and t.user_id = auth.uid() and t.status = 'in_progress'
    )
  );

create policy answers_update_own_open_attempt on public.assessment_answers
  for update to authenticated
  using (
    exists (
      select 1 from public.assessment_attempts t
       where t.id = attempt_id and t.user_id = auth.uid() and t.status = 'in_progress'
    )
  )
  with check (
    exists (
      select 1 from public.assessment_attempts t
       where t.id = attempt_id and t.user_id = auth.uid() and t.status = 'in_progress'
    )
  );

create policy answers_admin on public.assessment_answers
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- is_correct / points_awarded are written only by the definer scoring
-- function, which runs as the owner and is unaffected by these grants.
--
-- As with the answer key above, the table-level right has to be dropped first:
-- a column-level REVOKE against a role holding table-wide INSERT/UPDATE
-- changes nothing. After this, a learner can write an answer but cannot mark
-- it correct - not on insert, and not on a later update.
revoke insert, update on public.assessment_answers from authenticated;

grant insert (attempt_id, question_id, choice_ids, text_answer, answered_at)
  on public.assessment_answers to authenticated;
grant update (choice_ids, text_answer, answered_at)
  on public.assessment_answers to authenticated;

-- ==================================== training, resources, reference ======
--
-- Uniform rule: published is readable by any active user; admins do everything.
-- ---------------------------------------------------------------------------

do $$
declare
  t text;
  published_read_tables text[] := array[
    'training_activities',
    'practice_scenarios',
    'objections',
    'scripts',
    'wording_pairs',
    'quick_reference_items',
    'competencies'
  ];
begin
  foreach t in array published_read_tables loop
    execute format('alter table public.%I enable row level security', t);

    execute format($f$
      create policy %I on public.%I
        for select to authenticated
        using (public.is_admin() or (public.is_active_user() and status = 'published'))
    $f$, t || '_select', t);

    execute format($f$
      create policy %I on public.%I
        for all to authenticated
        using (public.is_admin()) with check (public.is_admin())
    $f$, t || '_admin', t);
  end loop;
end
$$;

-- Reference tables with no status column: readable by all, writable by admin.
do $$
declare
  t text;
  open_read_tables text[] := array[
    'competency_levels',
    'sales_bible_sections',
    'sales_bible_entries'
  ];
begin
  foreach t in array open_read_tables loop
    execute format('alter table public.%I enable row level security', t);
    execute format($f$
      create policy %I on public.%I
        for select to authenticated using (public.is_active_user())
    $f$, t || '_select', t);
    execute format($f$
      create policy %I on public.%I
        for all to authenticated
        using (public.is_admin()) with check (public.is_admin())
    $f$, t || '_admin', t);
  end loop;
end
$$;

alter table public.scenario_runs enable row level security;

create policy scenario_runs_own on public.scenario_runs
  for select to authenticated using (user_id = auth.uid() or public.is_admin());
create policy scenario_runs_insert_own on public.scenario_runs
  for insert to authenticated with check (user_id = auth.uid());

-- ------------------------------------------------------- user_competencies --

-- A learner may read their own competency ratings but never write one -
-- self-assessment would make the framework meaningless. Only admins rate.
alter table public.user_competencies enable row level security;

create policy user_competencies_select on public.user_competencies
  for select to authenticated
  using (user_id = auth.uid() or public.is_admin());

create policy user_competencies_admin on public.user_competencies
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- ======================================= assignments, progress, favourites =

alter table public.assignments enable row level security;

create policy assignments_select_own on public.assignments
  for select to authenticated using (user_id = auth.uid() or public.is_admin());

-- Learners may move their own assignment forward (start it), but may not
-- create one, reassign it, or change its due date. Pinning the identity
-- columns in WITH CHECK is what prevents an assignment being retargeted.
create policy assignments_update_own on public.assignments
  for update to authenticated
  using (user_id = auth.uid())
  with check (
    user_id = auth.uid()
    -- Qualify with the target table's name: a bare `id` would resolve to the
    -- subquery's own alias and match every row.
    and target_type = (select a.target_type from public.assignments a where a.id = assignments.id)
    and target_id   = (select a.target_id   from public.assignments a where a.id = assignments.id)
    and due_at      is not distinct from
        (select a.due_at from public.assignments a where a.id = assignments.id)
  );

create policy assignments_admin on public.assignments
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------- progress --

alter table public.module_progress enable row level security;

create policy module_progress_own on public.module_progress
  for all to authenticated
  using (user_id = auth.uid() or public.is_admin())
  with check (user_id = auth.uid() or public.is_admin());

alter table public.lesson_progress enable row level security;

create policy lesson_progress_own on public.lesson_progress
  for all to authenticated
  using (user_id = auth.uid() or public.is_admin())
  with check (user_id = auth.uid() or public.is_admin());

-- -------------------------------------------------------------- favourites --

alter table public.favorites enable row level security;

-- Strictly private: not even an admin needs to see what someone bookmarked.
create policy favorites_own on public.favorites
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- ----------------------------------------------------------- notifications --

alter table public.notifications enable row level security;

create policy notifications_select_own on public.notifications
  for select to authenticated using (user_id = auth.uid());

-- Marking as read is the only self-service change; the row is otherwise
-- immutable to its recipient.
create policy notifications_update_own on public.notifications
  for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

create policy notifications_admin on public.notifications
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- ----------------------------------------------------------- announcements --

alter table public.announcements enable row level security;

create policy announcements_select on public.announcements
  for select to authenticated
  using (
    public.is_admin()
    or (
      public.is_active_user()
      and status = 'published'
      and (published_at is null or published_at <= now())
      and (expires_at is null or expires_at > now())
      and (select p.role from public.profiles p where p.id = auth.uid()) = any (audience)
    )
  );

create policy announcements_admin on public.announcements
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- ------------------------------------------------------------ activity log --

alter table public.activity_logs enable row level security;

-- Admin-only, read-only (§38). Writes go through log_activity(), which is
-- definer - so a learner's genuine actions are recorded while a learner's
-- client cannot insert a fabricated entry or read anyone's history.
create policy activity_logs_admin_select on public.activity_logs
  for select to authenticated using (public.is_admin());

create policy activity_logs_admin_write on public.activity_logs
  for insert to authenticated with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- Function execution rights. Definer functions are the privileged paths in
-- this schema, so their EXECUTE grants are as much a part of the security
-- surface as the policies above.
-- ---------------------------------------------------------------------------
revoke execute on function public.submit_assessment_attempt(uuid) from public, anon;
revoke execute on function public.start_assessment_attempt(uuid)  from public, anon;
revoke execute on function public.log_activity(text, text, uuid, text, jsonb) from public, anon;
revoke execute on function public.touch_last_login() from public, anon;

grant execute on function public.submit_assessment_attempt(uuid) to authenticated;
grant execute on function public.start_assessment_attempt(uuid)  to authenticated;
grant execute on function public.log_activity(text, text, uuid, text, jsonb) to authenticated;
grant execute on function public.touch_last_login() to authenticated;
grant execute on function public.is_admin()        to authenticated;
grant execute on function public.is_active_user()  to authenticated;


-- ###########################################################################
-- ## 20260910090700_storage.sql
-- ###########################################################################

-- ============================================================================
-- 0008 - Storage buckets and their access policies (§41).
--
-- Three buckets, all private. Nothing here is public-read: this is an internal
-- tool, and a public bucket would make every uploaded asset reachable by URL
-- with no authentication at all.
-- ============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  -- Profile pictures. Small, images only.
  ('avatars', 'avatars', false, 2 * 1024 * 1024,
   array['image/png','image/jpeg','image/webp','image/gif']),

  -- Images and video used inside lesson content.
  ('learning-assets', 'learning-assets', false, 25 * 1024 * 1024,
   array['image/png','image/jpeg','image/webp','image/svg+xml','video/mp4','video/webm']),

  -- Documents attached to modules or activities.
  ('attachments', 'attachments', false, 25 * 1024 * 1024,
   array['application/pdf','image/png','image/jpeg','image/webp',
         'text/plain','text/csv',
         'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
         'application/vnd.openxmlformats-officedocument.presentationml.presentation',
         'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'])
on conflict (id) do update
  set file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types,
      public             = excluded.public;

-- ---------------------------------------------------------------------------
-- avatars
--
-- Convention: a user's files live under a folder named with their uid, so
-- `storage.foldername(name)[1]` is the owner. That makes ownership a property
-- of the path rather than a separate column that could drift out of sync.
-- ---------------------------------------------------------------------------
create policy "avatars readable by signed-in users"
  on storage.objects for select to authenticated
  using (bucket_id = 'avatars' and public.is_active_user());

create policy "avatars writable by owner"
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "avatars updatable by owner"
  on storage.objects for update to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);

create policy "avatars deletable by owner or admin"
  on storage.objects for delete to authenticated
  using (
    bucket_id = 'avatars'
    and ((storage.foldername(name))[1] = auth.uid()::text or public.is_admin())
  );

-- ---------------------------------------------------------------------------
-- learning-assets and attachments: readable by any active user (they are
-- embedded in published lessons), writable by admins only.
-- ---------------------------------------------------------------------------
create policy "learning assets readable by signed-in users"
  on storage.objects for select to authenticated
  using (bucket_id in ('learning-assets','attachments') and public.is_active_user());

create policy "learning assets managed by admins"
  on storage.objects for insert to authenticated
  with check (bucket_id in ('learning-assets','attachments') and public.is_admin());

create policy "learning assets updatable by admins"
  on storage.objects for update to authenticated
  using (bucket_id in ('learning-assets','attachments') and public.is_admin());

create policy "learning assets deletable by admins"
  on storage.objects for delete to authenticated
  using (bucket_id in ('learning-assets','attachments') and public.is_admin());


-- ###########################################################################
-- ## 20260910090800_rpc_and_reporting.sql
-- ###########################################################################

-- ============================================================================
-- 0009 - Remote procedures.
--
-- Two kinds of thing live here:
--   1. Writes that must be atomic or must run with elevated rights.
--   2. Aggregates that would otherwise mean shipping every row to the browser
--      and reducing it in React (§28: "Do not calculate everything only in
--      React"). A dashboard tile should cost one round trip, not a table scan
--      over the network.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Saves a question and its choices as one unit.
--
-- The builder's UI edits a question and its options together, so they must
-- commit together: a question that lands without its choices is unanswerable,
-- and half-written choices would fail validate_question_choices() later at
-- an unhelpful moment. Deleting and re-inserting the choices is deliberate -
-- it keeps sort_order contiguous without a diffing algorithm on the client.
-- ---------------------------------------------------------------------------
create or replace function public.admin_save_question(
  p_assessment_id uuid,
  p_question_id   uuid,          -- null to create
  p_type          public.question_type,
  p_prompt        text,
  p_explanation   text,
  p_points        int,
  p_sort_order    int,
  p_correct_text  text,          -- short_answer only
  p_choices       jsonb          -- [{ text, is_correct }] in display order
) returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
  v_choice jsonb;
  v_i int := 0;
begin
  if not public.is_admin() then
    raise exception 'Only an admin may edit assessment questions';
  end if;

  if p_question_id is null then
    insert into public.assessment_questions
      (assessment_id, type, prompt, explanation, points, sort_order, correct_text)
    values
      (p_assessment_id, p_type, p_prompt, coalesce(p_explanation,''), coalesce(p_points,1),
       coalesce(p_sort_order,0), case when p_type = 'short_answer' then p_correct_text end)
    returning id into v_id;
  else
    update public.assessment_questions
       set type = p_type,
           prompt = p_prompt,
           explanation = coalesce(p_explanation,''),
           points = coalesce(p_points,1),
           sort_order = coalesce(p_sort_order, sort_order),
           correct_text = case when p_type = 'short_answer' then p_correct_text end
     where id = p_question_id and assessment_id = p_assessment_id
     returning id into v_id;

    if v_id is null then
      raise exception 'Question % does not belong to assessment %', p_question_id, p_assessment_id;
    end if;

    delete from public.assessment_choices where question_id = v_id;
  end if;

  if p_type <> 'short_answer' then
    for v_choice in select * from jsonb_array_elements(coalesce(p_choices, '[]'::jsonb))
    loop
      insert into public.assessment_choices (question_id, text, is_correct, sort_order)
      values (
        v_id,
        v_choice ->> 'text',
        coalesce((v_choice ->> 'is_correct')::boolean, false),
        v_i
      );
      v_i := v_i + 1;
    end loop;

    -- Raises if the shape is wrong, rolling the whole call back.
    perform public.validate_question_choices(v_id);
  end if;

  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Bulk assignment (§27). One call for "assign to all sales users" instead of
-- N inserts from the browser, and it fans out the notifications in the same
-- transaction so nobody is assigned work they are never told about.
-- ---------------------------------------------------------------------------
create or replace function public.admin_assign(
  p_user_ids    uuid[],
  p_target_type public.assignment_target,
  p_target_id   uuid,
  p_due_at      timestamptz default null,
  p_note        text default ''
) returns int
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_count int;
  v_label text;
begin
  if not public.is_admin() then
    raise exception 'Only an admin may assign training';
  end if;

  select case p_target_type
    when 'module'     then (select title from public.modules             where id = p_target_id)
    when 'path'       then (select title from public.learning_paths      where id = p_target_id)
    when 'assessment' then (select title from public.assessments         where id = p_target_id)
    when 'activity'   then (select title from public.training_activities where id = p_target_id)
  end into v_label;

  if v_label is null then
    raise exception 'No % exists with id %', p_target_type, p_target_id;
  end if;

  with upserted as (
    insert into public.assignments (user_id, target_type, target_id, assigned_by, due_at, note)
    select uid, p_target_type, p_target_id, auth.uid(), p_due_at, coalesce(p_note,'')
      from unnest(p_user_ids) as uid
    -- Re-assigning refreshes the deadline rather than erroring or duplicating.
    on conflict (user_id, target_type, target_id) do update
      set due_at = excluded.due_at,
          note = excluded.note,
          assigned_by = excluded.assigned_by,
          assigned_at = now()
    returning user_id
  )
  select count(*) into v_count from upserted;

  insert into public.notifications (user_id, kind, title, body)
  select uid, 'assignment', 'New training assigned', v_label
    from unnest(p_user_ids) as uid;

  perform public.log_activity(
    'assignment.created', p_target_type::text, p_target_id, v_label,
    jsonb_build_object('recipients', coalesce(array_length(p_user_ids, 1), 0))
  );

  return v_count;
end;
$$;

-- ---------------------------------------------------------------------------
-- Role and status changes.
--
-- Routed through a function rather than a plain UPDATE so that (a) the last
-- admin cannot be demoted or deactivated, locking everyone out of the console,
-- and (b) every change is audited without relying on the caller to log it.
-- ---------------------------------------------------------------------------
create or replace function public.admin_set_user_role(
  p_user_id uuid,
  p_role    public.user_role
) returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_admins int;
  v_current public.user_role;
  v_name text;
begin
  if not public.is_admin() then
    raise exception 'Only an admin may change roles';
  end if;

  select role, full_name into v_current, v_name from public.profiles where id = p_user_id;
  if v_current is null then
    raise exception 'No such user';
  end if;

  if v_current = 'admin' and p_role <> 'admin' then
    select count(*) into v_admins
      from public.profiles where role = 'admin' and status = 'active';
    if v_admins <= 1 then
      raise exception 'Cannot remove the last active admin';
    end if;
  end if;

  update public.profiles set role = p_role where id = p_user_id;

  perform public.log_activity('user.role_changed', 'profile', p_user_id, v_name,
    jsonb_build_object('from', v_current, 'to', p_role));
end;
$$;

create or replace function public.admin_set_user_status(
  p_user_id uuid,
  p_status  public.user_status
) returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_admins int;
  v_name text;
  v_role public.user_role;
begin
  if not public.is_admin() then
    raise exception 'Only an admin may change account status';
  end if;

  select full_name, role into v_name, v_role from public.profiles where id = p_user_id;
  if v_name is null then
    raise exception 'No such user';
  end if;

  if v_role = 'admin' and p_status <> 'active' then
    select count(*) into v_admins from public.profiles where role = 'admin' and status = 'active';
    if v_admins <= 1 then
      raise exception 'Cannot deactivate the last active admin';
    end if;
  end if;

  update public.profiles set status = p_status where id = p_user_id;

  perform public.log_activity('user.status_changed', 'profile', p_user_id, v_name,
    jsonb_build_object('to', p_status));
end;
$$;

-- ---------------------------------------------------------------------------
-- Marks a lesson complete. Thin, but it exists so the client never has to know
-- the module_id or the upsert conflict target, and so the roll-up trigger is
-- guaranteed to fire through one code path.
-- ---------------------------------------------------------------------------
create or replace function public.complete_lesson(p_lesson_id uuid, p_completed boolean default true)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_module uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select module_id into v_module from public.lessons where id = p_lesson_id;
  if v_module is null then
    raise exception 'No such lesson';
  end if;

  insert into public.lesson_progress (user_id, lesson_id, module_id, completed, completed_at)
  values (auth.uid(), p_lesson_id, v_module, p_completed,
          case when p_completed then now() end)
  on conflict (user_id, lesson_id) do update
    set completed = p_completed,
        completed_at = case when p_completed then coalesce(lesson_progress.completed_at, now()) end;
end;
$$;

-- Records that a module was opened, so "Continue learning" has something to
-- point at before any lesson is finished.
create or replace function public.touch_module_view(p_module_id uuid, p_lesson_id uuid default null)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null then return; end if;

  insert into public.module_progress as mp
    (user_id, module_id, state, started_at, last_viewed_at, last_viewed_lesson_id)
  values (auth.uid(), p_module_id, 'in-progress', now(), now(), p_lesson_id)
  on conflict (user_id, module_id) do update
    set last_viewed_at = now(),
        last_viewed_lesson_id = coalesce(p_lesson_id, mp.last_viewed_lesson_id),
        started_at = coalesce(mp.started_at, now()),
        -- Viewing must never downgrade a finished module back to in-progress.
        state = case when mp.state = 'completed' then 'completed' else 'in-progress' end;
end;
$$;

-- ===========================================================================
-- Reporting
-- ===========================================================================

-- Admin dashboard tiles (§30) in a single round trip. Returns zeros rather
-- than nulls on an empty database so the UI can distinguish "no data yet"
-- from "query failed".
create or replace function public.admin_dashboard_stats()
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v jsonb;
begin
  if not public.is_admin() then
    raise exception 'Admins only';
  end if;

  select jsonb_build_object(
    'sales_users',        (select count(*) from public.profiles where role = 'sales'),
    'active_users',       (select count(*) from public.profiles where status = 'active'),
    'pending_users',      (select count(*) from public.profiles where status = 'pending'),
    'published_modules',  (select count(*) from public.modules where status = 'published'),
    'draft_modules',      (select count(*) from public.modules where status = 'draft'),
    'active_paths',       (select count(*) from public.learning_paths where status = 'published'),
    'published_assessments', (select count(*) from public.assessments where status = 'published'),
    'pending_assignments',(select count(*) from public.assignments where status <> 'completed'),
    'overdue_assignments',(select count(*) from public.assignments
                            where status <> 'completed' and due_at is not null and due_at < now()),
    'avg_completion',     coalesce((
        -- Completion is measured per learner across published modules, so a
        -- newly published module correctly drags the average down.
        select round(avg(pct), 1) from (
          select p.id,
                 case when total.n = 0 then 0
                      else (count(mp.*) filter (where mp.state = 'completed')::numeric / total.n) * 100
                 end as pct
            from public.profiles p
            cross join (select count(*) as n from public.modules where status = 'published') total
            left join public.module_progress mp on mp.user_id = p.id
           where p.role = 'sales' and p.status = 'active'
           group by p.id, total.n
        ) per_user
      ), 0),
    'avg_assessment_score', coalesce((
        select round(avg(percentage), 1) from public.assessment_attempts where status = 'submitted'
      ), 0),
    'pass_rate', coalesce((
        select round(100.0 * count(*) filter (where passed) / nullif(count(*), 0), 1)
          from public.assessment_attempts where status = 'submitted'
      ), 0),
    'attempts_last_30d', (
        select count(*) from public.assessment_attempts
         where status = 'submitted' and submitted_at > now() - interval '30 days'
      ),
    'lessons_completed_last_7d', (
        select count(*) from public.lesson_progress
         where completed and completed_at > now() - interval '7 days'
      )
  ) into v;

  return v;
end;
$$;

-- Per-learner training completion (§31). One row per active sales user.
create or replace function public.report_training_completion()
returns table (
  user_id uuid,
  full_name text,
  department text,
  -- Included rather than filtered on: a deactivated employee's training record
  -- is still part of the history, and hiding the row would silently change the
  -- denominator of any average taken over this report. The admin table filters.
  status public.user_status,
  modules_completed bigint,
  modules_in_progress bigint,
  modules_total bigint,
  completion_percent numeric,
  assessments_taken bigint,
  avg_score numeric
)
language sql
security definer
set search_path = public, pg_temp
as $$
  select
    p.id,
    p.full_name,
    coalesce(p.department, ''),
    p.status,
    count(mp.*) filter (where mp.state = 'completed'),
    count(mp.*) filter (where mp.state = 'in-progress'),
    total.n,
    case when total.n = 0 then 0
         else round((count(mp.*) filter (where mp.state = 'completed')::numeric / total.n) * 100, 1)
    end,
    (select count(*) from public.assessment_attempts a
      where a.user_id = p.id and a.status = 'submitted'),
    coalesce((select round(avg(a.percentage), 1) from public.assessment_attempts a
      where a.user_id = p.id and a.status = 'submitted'), 0)
  from public.profiles p
  cross join (select count(*) as n from public.modules where status = 'published') total
  left join public.module_progress mp on mp.user_id = p.id
  where public.is_admin() and p.role = 'sales'
  group by p.id, p.full_name, p.department, p.status, total.n
  order by p.full_name;
$$;

-- Per-assessment performance (§31).
create or replace function public.report_assessment_performance()
returns table (
  assessment_id uuid,
  title text,
  attempts bigint,
  unique_takers bigint,
  avg_score numeric,
  pass_rate numeric,
  passing_score int
)
language sql
security definer
set search_path = public, pg_temp
as $$
  select
    a.id,
    a.title,
    count(t.*),
    count(distinct t.user_id),
    coalesce(round(avg(t.percentage), 1), 0),
    coalesce(round(100.0 * count(*) filter (where t.passed) / nullif(count(t.*), 0), 1), 0),
    a.passing_score
  from public.assessments a
  left join public.assessment_attempts t
    on t.assessment_id = a.id and t.status = 'submitted'
  where public.is_admin()
  group by a.id, a.title, a.passing_score
  order by a.title;
$$;

-- Engagement per module: what gets opened, what gets finished, what stalls.
create or replace function public.report_module_engagement()
returns table (
  module_id uuid,
  title text,
  status public.content_status,
  learners_started bigint,
  learners_completed bigint,
  completion_percent numeric
)
language sql
security definer
set search_path = public, pg_temp
as $$
  select
    m.id,
    m.title,
    m.status,
    count(mp.*) filter (where mp.state <> 'not-started'),
    count(mp.*) filter (where mp.state = 'completed'),
    coalesce(round(
      100.0 * count(mp.*) filter (where mp.state = 'completed')
      / nullif(count(mp.*) filter (where mp.state <> 'not-started'), 0), 1), 0)
  from public.modules m
  left join public.module_progress mp on mp.module_id = m.id
  where public.is_admin()
  group by m.id, m.title, m.status
  order by m.title;
$$;

-- The learner's own dashboard roll-up, mirroring admin_dashboard_stats().
create or replace function public.my_progress_summary()
returns jsonb
language sql
security definer
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
    'modules_total',     (select count(*) from public.modules where status = 'published'),
    'modules_completed', (select count(*) from public.module_progress
                           where user_id = auth.uid() and state = 'completed'),
    'modules_in_progress',(select count(*) from public.module_progress
                           where user_id = auth.uid() and state = 'in-progress'),
    'lessons_completed', (select count(*) from public.lesson_progress
                           where user_id = auth.uid() and completed),
    'assignments_open',  (select count(*) from public.assignments
                           where user_id = auth.uid() and status <> 'completed'),
    'assignments_overdue',(select count(*) from public.assignments
                           where user_id = auth.uid() and status <> 'completed'
                             and due_at is not null and due_at < now()),
    'attempts',          (select count(*) from public.assessment_attempts
                           where user_id = auth.uid() and status = 'submitted'),
    'avg_score',         coalesce((select round(avg(percentage),1) from public.assessment_attempts
                           where user_id = auth.uid() and status = 'submitted'), 0),
    'passed',            (select count(*) from public.assessment_attempts
                           where user_id = auth.uid() and status = 'submitted' and passed)
  );
$$;

-- --------------------------------------------------------------- grants ----

-- Same reasoning as 0007: strip the implicit PUBLIC grant, then hand EXECUTE
-- back to `authenticated` one function at a time. Anything omitted below is
-- reachable only from inside another definer function or a trigger.
revoke execute on all functions in schema public from public, anon;

grant execute on function public.admin_save_question(uuid, uuid, public.question_type, text, text, int, int, text, jsonb) to authenticated;
grant execute on function public.admin_assign(uuid[], public.assignment_target, uuid, timestamptz, text) to authenticated;
grant execute on function public.admin_set_user_role(uuid, public.user_role) to authenticated;
grant execute on function public.admin_set_user_status(uuid, public.user_status) to authenticated;
grant execute on function public.complete_lesson(uuid, boolean) to authenticated;
grant execute on function public.touch_module_view(uuid, uuid) to authenticated;
grant execute on function public.admin_dashboard_stats() to authenticated;
grant execute on function public.report_training_completion() to authenticated;
grant execute on function public.report_assessment_performance() to authenticated;
grant execute on function public.report_module_engagement() to authenticated;
grant execute on function public.my_progress_summary() to authenticated;
grant execute on function public.submit_assessment_attempt(uuid) to authenticated;
grant execute on function public.start_assessment_attempt(uuid) to authenticated;
grant execute on function public.log_activity(text, text, uuid, text, jsonb) to authenticated;
grant execute on function public.touch_last_login() to authenticated;
grant execute on function public.is_admin() to authenticated;
grant execute on function public.is_active_user() to authenticated;
grant execute on function public.assignment_effective_status(public.assignment_status, timestamptz) to authenticated;


-- ###########################################################################
-- ## 20260910090900_attempt_review.sql
-- ###########################################################################

-- ============================================================================
-- 0010 - Attempt review.
--
-- §17 requires the results screen to show which answers were right, which were
-- wrong, and the explanation - while §17 equally requires that none of that is
-- available before submission.
--
-- Those two rules cannot both be satisfied by a table grant: the answer key is
-- withheld from `authenticated` at the column level (0007), so there is no
-- query a learner can run that returns it. This function is the one controlled
-- exception. It is SECURITY DEFINER, and it releases the key only when all of
-- the following hold:
--
--   * the attempt belongs to the caller (or the caller is an admin),
--   * the attempt has actually been submitted, and
--   * the assessment has show_correct_answers = true.
--
-- Miss any one and it raises. The key is therefore reachable exactly once the
-- learner can no longer use it to answer.
-- ============================================================================

create or replace function public.attempt_review(p_attempt_id uuid)
returns table (
  question_id     uuid,
  prompt          text,
  type            public.question_type,
  points          int,
  sort_order      int,
  explanation     text,
  -- What the learner picked, and what was right.
  selected_choice_ids uuid[],
  correct_choice_ids  uuid[],
  text_answer     text,
  correct_text    text,
  is_correct      boolean,
  points_awarded  int
)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_attempt public.assessment_attempts;
  v_reveal  boolean;
begin
  select * into v_attempt from public.assessment_attempts where id = p_attempt_id;

  if v_attempt.id is null then
    raise exception 'Attempt not found';
  end if;

  if v_attempt.user_id <> auth.uid() and not public.is_admin() then
    raise exception 'That attempt is not yours';
  end if;

  if v_attempt.status <> 'submitted' then
    raise exception 'This attempt has not been submitted yet';
  end if;

  select a.show_correct_answers into v_reveal
    from public.assessments a where a.id = v_attempt.assessment_id;

  -- An admin reviewing someone's attempt always sees the key; a learner sees
  -- it only if the assessment was configured to reveal it.
  v_reveal := coalesce(v_reveal, true) or public.is_admin();

  return query
  select
    q.id,
    q.prompt,
    q.type,
    q.points,
    q.sort_order,
    -- The explanation is part of the feedback, so it follows the same gate.
    case when v_reveal then q.explanation else '' end,
    coalesce(ans.choice_ids, '{}'),
    case
      when v_reveal then coalesce(
        (select array_agg(c.id order by c.sort_order)
           from public.assessment_choices c
          where c.question_id = q.id and c.is_correct),
        '{}')
      else '{}'
    end,
    ans.text_answer,
    case when v_reveal then q.correct_text end,
    -- Written by the scoring function at submission, so this is the verdict
    -- that produced the score rather than a re-derivation.
    ans.is_correct,
    coalesce(ans.points_awarded, 0)
  from public.assessment_questions q
  left join public.assessment_answers ans
    on ans.question_id = q.id and ans.attempt_id = p_attempt_id
  where q.assessment_id = v_attempt.assessment_id
  order by q.sort_order;
end;
$$;

comment on function public.attempt_review(uuid) is
  'Post-submission review including the answer key. The only sanctioned path to '
  'assessment_choices.is_correct for a non-admin, gated on the attempt being '
  'submitted and owned by the caller.';

revoke execute on function public.attempt_review(uuid) from public, anon;
grant execute on function public.attempt_review(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Records an answer while an attempt is open.
--
-- Exists so the runner can save progress with one upsert per question without
-- needing to know whether a row already exists. The RLS policies on
-- assessment_answers still apply: this is SECURITY INVOKER, unlike the
-- functions above, precisely so a learner cannot use it to write into someone
-- else's attempt.
-- ---------------------------------------------------------------------------
create or replace function public.save_answer(
  p_attempt_id  uuid,
  p_question_id uuid,
  p_choice_ids  uuid[] default '{}',
  p_text_answer text default null
) returns void
language sql
set search_path = public, pg_temp
as $$
  insert into public.assessment_answers (attempt_id, question_id, choice_ids, text_answer)
  values (p_attempt_id, p_question_id, coalesce(p_choice_ids, '{}'), p_text_answer)
  on conflict (attempt_id, question_id) do update
    set choice_ids  = excluded.choice_ids,
        text_answer = excluded.text_answer,
        answered_at = now();
$$;

revoke execute on function public.save_answer(uuid, uuid, uuid[], text) from public, anon;
grant execute on function public.save_answer(uuid, uuid, uuid[], text) to authenticated;


-- ###########################################################################
-- ## 20260910091000_rbac_and_invitations.sql
-- ###########################################################################

-- ============================================================================
-- 0011 - Invitation-only accounts, and permission-based access control.
--
-- Two changes, and they are related.
--
-- 1. NOBODY CAN SIGN THEMSELVES UP.
--    `handle_new_user` now refuses any signup with no matching invitation.
--    That covers email/password AND Google OAuth, because both funnel through
--    the same trigger on auth.users - so this is not a dashboard toggle that
--    can be flipped back by accident, it is a database rule.
--
-- 2. ACCESS IS A SET OF PERMISSIONS, NOT JUST A ROLE.
--    `role` (admin | sales) stays as the coarse gate that decides who sees the
--    admin console at all. What a person may actually DO is now a permission
--    set: defaults come from their role, and an admin can grant or revoke any
--    individual permission per person.
--
--    Existing behaviour is preserved exactly: admins are granted every
--    permission by default, so `can('content.edit')` is true for an admin for
--    the same reason `is_admin()` was.
--
-- Creating the auth user itself still needs the service role key, which must
-- never reach the browser. The invitation flow is how an admin provisions an
-- account without it: the admin records who may join and with what access, and
-- the person sets their own password. The admin never learns it, which is
-- better than the alternative.
-- ============================================================================

-- =========================================================== permissions ====

create table public.permissions (
  key         text primary key check (key ~ '^[a-z_]+\.[a-z_]+$'),
  label       text not null,
  description text not null default '',
  -- Groups the admin UI's checklist. Not a security boundary.
  category    text not null,
  sort_order  int  not null default 0
);

comment on table public.permissions is
  'The catalogue of things a person can be allowed to do. Rows are seeded by '
  'this migration; the application never invents a key at runtime.';

insert into public.permissions (key, label, description, category, sort_order) values
  -- Learning content
  ('content.view_drafts', 'View drafts',        'See unpublished materials.',                     'Content',  10),
  ('content.create',      'Create materials',   'Add new modules and lessons.',                   'Content',  11),
  ('content.edit',        'Edit materials',      'Change existing modules, lessons and blocks.',  'Content',  12),
  ('content.publish',     'Publish materials',   'Make a material visible to sales users.',      'Content',  13),
  ('content.archive',     'Archive materials',   'Withdraw a material without deleting it.',     'Content',  14),
  ('categories.manage',   'Manage categories',   'Add, rename and remove categories.',           'Content',  15),

  -- Assessments
  ('assessments.create',  'Create assessments',  'Add new assessments.',                          'Assessments', 20),
  ('assessments.edit',    'Edit assessments',    'Change questions, options and answer keys.',    'Assessments', 21),
  ('assessments.publish', 'Publish assessments', 'Make an assessment available to take.',         'Assessments', 22),
  ('assessments.results', 'View all results',    'See every learner''s attempts and scores.',     'Assessments', 23),

  -- Training
  ('training.manage',     'Manage activities',   'Add and edit facilitator-led activities.',      'Training', 30),
  ('scenarios.manage',    'Manage scenarios',    'Add and edit practice scenarios.',              'Training', 31),

